function updateFaqFile(filePath, categoryName, newFaqs) {
  if (!fs.existsSync(filePath)) {
    console.error(`File not found: ${filePath}`);
    return;
  }

  const raw = fs.readFileSync(filePath, 'utf8');
  const data = JSON.parse(raw);
  
  // Find category
  const categoryIndex = data.categories.findIndex(c => c.category === categoryName);
  if (categoryIndex === -1) {
    console.error(`Category not found: ${categoryName} in ${filePath}`);
    return;
  }

  const currentFaqs = data.categories[categoryIndex].faqs;
  
  // Filter out any duplicate questions if they already exist
  const existingQuestions = new Set(currentFaqs.map(f => f.question.toLowerCase().trim()));
  const faqsToAdd = newFaqs.filter(f => !existingQuestions.has(f.question.toLowerCase().trim()));
  
  data.categories[categoryIndex].faqs = [...currentFaqs, ...faqsToAdd];
  
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf8');
  console.log(`Successfully updated ${filePath}. Added ${faqsToAdd.length} FAQs to "${categoryName}".`);
}

const bnPath = path.join(__dirname, '../content/bn/faq.json');
const enPath = path.join(__dirname, '../content/en/faq.json');

updateFaqFile(bnPath, "কণ্ঠস্বর অনুসন্ধান (ভয়েস সার্চ)", bnFaqs);
updateFaqFile(enPath, "Conversational Voice Queries", enFaqs);
